test("names reveal gradually while keyboard focus reveals a row immediately", async ({
  page,
  backend,
}) => {
  await backend.route("**/api/rankings", async (route) =>
    route.fulfill({ json: rankingFixture }),
  );
  await page.emulateMedia({ reducedMotion: "no-preference" });
  await page.goto("/rankings");
  const lastRow = page
    .getByRole("list", { name: "MPs rankings" })
    .getByRole("listitem")
    .last();
