  const initialBounds = await name.boundingBox();
  expect(
    await name.evaluate((element) => Number(getComputedStyle(element).opacity)),
  ).toBeLessThan(1);
  await name.focus();
  await expect(name).toBeFocused();
  expect(
    await lastRow.evaluate((element) => getComputedStyle(element).opacity),
  ).toBe("1");
  expect(
    await name.evaluate((element) => ({
      opacity: getComputedStyle(element).opacity,
      clip: getComputedStyle(element).clipPath,
    })),
  ).toEqual({ opacity: "1", clip: "inset(0px 0% 0px 0px)" });
  await page.getByRole("button", { name: "MPs", exact: true }).focus();
  expect(
    await lastRow.evaluate((element) => getComputedStyle(element).opacity),
  ).toBe("1");
  expect(
    await name.evaluate((element) => ({
      opacity: getComputedStyle(element).opacity,
      clip: getComputedStyle(element).clipPath,
    })),
  ).toEqual({ opacity: "1", clip: "inset(0px 0% 0px 0px)" });
  expect((await name.boundingBox())?.width).toBe(initialBounds?.width);
  await expect(lastRow).toContainText("£");
});

