import { expect, test } from "./backend";
import { rankingFixture } from "./rankings-fixtures";

test("rankings starts unselected and category switching is immediate and local", async ({
  page,
  backend,
  request,
  baseURL,
}) => {
  let reads = 0;
  await backend.route("**/api/rankings", async (route) => {
    reads += 1;
    await route.fulfill({ json: rankingFixture });
  });
  const ssr = await request.get(`${baseURL}/rankings`);
  const html = await ssr.text();
  expect(html).not.toContain('aria-label="MPs rankings"');
  expect(html).not.toContain('class="board"');
  expect(html.match(/aria-pressed="false"/gu)).toHaveLength(4);
  await page.goto("/");
  await page.getByRole("link", { name: "Rankings", exact: true }).click();
  await expect(page.getByRole("heading", { level: 1 })).toHaveText("Rankings");
  await expect(page.locator(".board")).toHaveCount(0);
  await expect(page.getByText("No declarations found.")).toHaveCount(0);
  await expect(
    page.getByText("All donations for this parliamentary term"),
  ).toBeVisible();
  await expect(
    page.locator('.category-wheel button[aria-pressed="false"]'),
  ).toHaveCount(4);
  await expect(page.locator(".category-wheel path.selected")).toHaveCount(0);
  await page.getByRole("button", { name: "MPs", exact: true }).click();
  const rows = page.getByRole("list", { name: "MPs rankings" });
  await expect(rows.getByRole("listitem")).toHaveCount(10);
  await expect(
    rows.getByRole("link", { name: "Member 1", exact: true }),
  ).toHaveAttribute("href", "/members/1");
  await expect(rows).toContainText("£9,007,199,254,740,993.123456789");
  await expect(rows).toContainText("Incomplete");
  await expect(rows).toContainText("Example Party · Example constituency");
  await expect(
    page.getByText("All declared amounts for this parliamentary term"),
  ).toBeVisible();
  const before = reads;
  const individuals = page.getByRole("button", { name: "Individuals" });
  await individuals.focus();
  await page.keyboard.press("Space");
  await expect(individuals).toBeFocused();
  await expect(individuals).toHaveAttribute("aria-pressed", "true");
  await expect(
    page.locator('.category-wheel button[aria-pressed="true"]'),
  ).toHaveCount(1);
  await expect(
    page.getByRole("group", { name: "Ranking category" }),
  ).not.toContainText("✓");
  await expect(
    page.getByRole("list", { name: "Individuals rankings" }),
  ).toContainText("£0.00");
  await expect(
    page.getByText("All donations for this parliamentary term"),
  ).toBeVisible();
  await page
    .getByRole("button", { name: "Companies" })
    .click({ position: { x: 20, y: 20 } });
  await expect(page.locator(".category-wheel path.selected")).toHaveCSS(
    "stroke",
    "rgb(100, 207, 181)",
  );
  await expect(
    page.getByRole("link", { name: "Example company" }),
  ).toHaveAttribute("href", "/funders/10000000-0000-0000-0000-000000000002");
  await expect(
    page.getByRole("list", { name: "Companies rankings" }),
  ).toContainText("−£12.3456789");
  await page.getByRole("button", { name: "Parties" }).click();
  const parties = page.getByRole("list", { name: "Parties rankings" });
  await expect(parties).toContainText("Amount unavailable");
  await expect(parties.getByRole("link")).toHaveCount(0);
  await expect(
    page.getByText("Support declared by MPs, grouped by their latest party."),
  ).toBeVisible();
  expect(reads).toBe(before);
  await page.reload();
  await expect(page.locator(".board")).toHaveCount(0);
  await expect(
    page.locator('.category-wheel button[aria-pressed="false"]'),
  ).toHaveCount(4);
  await page.goto("/");
  await page.getByRole("link", { name: "Rankings", exact: true }).click();
  await expect(page.locator(".board")).toHaveCount(0);
  await expect(
    page.getByRole("button", { name: /All records|Show more|Replay/u }),
  ).toHaveCount(0);
});

test("rankings fit narrow viewports and honor reduced motion", async ({
  page,
  backend,
}) => {
  await backend.route("**/api/rankings", async (route) =>
    route.fulfill({ json: rankingFixture }),
  );
  await page.setViewportSize({ width: 320, height: 900 });
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.goto("/rankings");
  await page.getByRole("button", { name: "MPs", exact: true }).click();
  await expect(
    page.getByRole("list", { name: "MPs rankings" }).getByRole("listitem"),
  ).toHaveCount(10);
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBe(
    320,
  );
  const row = page.getByRole("listitem").first();
  await expect(row).toHaveCSS("animation-name", "none");
  await expect(row.getByRole("link")).toHaveCSS("animation-name", "none");
  await expect(row.locator(".bar-track > span")).toHaveCSS(
    "animation-name",
    "none",
  );
  await page.getByRole("button", { name: "Companies" }).click();
  await expect(page.getByRole("listitem").first()).toHaveCSS(
    "animation-name",
    "none",
  );
});
test("category wheel starts precoloured and uses a selected rim with neutral focus", async ({
  page,
}) => {
  await page.goto("/design-system", { waitUntil: "networkidle" });
  const selector = page.getByRole("group", {
